-- Seed data awal hasil ekstraksi KMZ. Verifikasi sebelum dipakai sebagai data resmi.
on conflict (id) do update set name=excluded.name, latitude=excluded.latitude, longitude=excluded.longitude, korsda=excluded.korsda, no_pos=excluded.no_pos, elevation=excluded.elevation, rainfall=excluded.rainfall, status=excluded.status, notes=excluded.notes, source_properties=excluded.source_properties, updated_at=now();
